          "stepType": "ScriptOutput",
          "name": "Generate HR Case Summary",
          "output_type": "single_part",
          "script": "(function execute() {\n\n    var caseId = vaInputs.hr_case_lookup;\n\n    var gr = new GlideRecord('x_snc_unified_hr_0_hr_case');\n\n    if (gr.get(caseId)) {\n\n        var response = '';\n\n        response += 'Here is the summary of your HR case:\\n\\n';\n\n        response += 'Case Number: ' + gr.getDisplayValue('number') + '\\n';\n        response += 'Requested By: ' + gr.getDisplayValue('request_by') + '\\n';\n        response += 'Category: ' + gr.getDisplayValue('category') + '\\n';\n        response += 'Priority: ' + gr.getDisplayValue('priority') + '\\n';\n        response += 'Status: ' + gr.getDisplayValue('status') + '\\n';\n        response += 'Assignment Group: ' + gr.getDisplayValue('assignment_group') + '\\n';\n        response += 'Assigned To: ' + gr.getDisplayValue('assigned_to') + '\\n\\n';\n\n        response += 'Issue:\\n';\n        response += gr.getDisplayValue('description') + '\\n\\n';\n\n        if (gr.getValue('resolution_notes')) {\n            response += 'Resolution / Actions:\\n';\n            response += gr.getDisplayValue('resolution_notes') + '\\n\\n';\n        }\n\n        if (gr.getValue('rejection_feedback')) {\n            response += 'Rejection Feedback:\\n';\n            response += gr.getDisplayValue('rejection_feedback') + '\\n';\n        }\n\n        return response;\n\n    }\n\n    return 'I could not find the requested HR case.';\n\n})()",
